from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    period = len(colors) + 1

    # Horizontal bands encode a periodic row-color sequence.
    full_rows = [r for r, row in enumerate(grid)
                 if row and all(v == row[0] and v != 0 for v in row)]
    if full_rows:
        buckets = defaultdict(Counter)
        for r, row in enumerate(grid):
            for v in row:
                if v:
                    buckets[r % period][v] += 1
        mapping = {k: c.most_common(1)[0][0] for k, c in buckets.items()}
        return [[mapping[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal markers encode colors by the c-r residue.
    buckets = defaultdict(Counter)
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                buckets[(c-r) % period][v] += 1
    mapping = {k: c.most_common(1)[0][0] for k, c in buckets.items()}
    return [[mapping[(c-r) % period] for c in range(w)] for r in range(h)]
